const config = $input.first().json;
if (!config.keywords) return [];
return config.keywords.split(',').map(k => ({ json: { keyword: k.trim(), apiKey: config.youtubeApiKey } })).filter(k => k.json.keyword);

const videos = [];
for (const item of $input.all()) {
  if (item.json.items) {
    for (const vid of item.json.items) {
      if (vid.id && vid.id.videoId) {
        videos.push({
          json: {
            videoId: vid.id.videoId,
            channelId: vid.snippet.channelId,
            title: vid.snippet.title,
            channelTitle: vid.snippet.channelTitle,
            publishedAt: vid.snippet.publishedAt
          }
        });
      }
    }
  }
}
return videos;

const config = $input.first().json;
if (!config.monitoredChannels) return [];
return config.monitoredChannels.split(',').map(c => ({ json: { channelId: c.trim() } })).filter(c => c.json.channelId);

const videos = [];
for (const item of $input.all()) {
  const feed = item.json.feed;
  if (feed && feed.entry) {
    const entries = Array.isArray(feed.entry) ? feed.entry : [feed.entry];
    for (const entry of entries) {
      videos.push({
        json: {
          videoId: entry['yt:videoId'],
          channelId: entry['yt:channelId'],
          title: entry.title,
          channelTitle: feed.title,
          publishedAt: entry.published
        }
      });
    }
  }
}
return videos;

const uniqueVideos = {};
for (const item of $input.all()) {
  if (item.json.videoId) {
    uniqueVideos[item.json.videoId] = item.json;
  }
}

const videoList = Object.values(uniqueVideos);
const chunks = [];
for (let i = 0; i < videoList.length; i += 50) {
  const batch = videoList.slice(i, i + 50);
  chunks.push({
    json: {
      videoIds: batch.map(v => v.videoId).join(','),
      videos: batch
    }
  });
}
return chunks;

const videos = [];
const channelIds = new Set();

for (const item of $input.all()) {
  if (item.json.items) {
    for (const vid of item.json.items) {
      const stats = vid.statistics || {};
      videos.push({
        videoId: vid.id,
        channelId: vid.snippet.channelId,
        title: vid.snippet.title,
        channelTitle: vid.snippet.channelTitle,
        publishedAt: vid.snippet.publishedAt,
        views: parseInt(stats.viewCount || '0', 10),
        likes: parseInt(stats.likeCount || '0', 10),
        comments: parseInt(stats.commentCount || '0', 10),
        duration: vid.contentDetails.duration
      });
      channelIds.add(vid.snippet.channelId);
    }
  }
}

const channelList = Array.from(channelIds);
const channelChunks = [];
for (let i = 0; i < channelList.length; i += 50) {
  channelChunks.push({
    json: {
      channelIds: channelList.slice(i, i + 50).join(','),
      videos: videos
    }
  });
}
return channelChunks;

const config = $('Config').item.json;
const minViews = config.minViews || 1000;
const maxSubscribers = config.maxSubscribers || 150000;
const outlierRatioThreshold = config.outlierRatioThreshold || 2;

const channelsMap = {};
for (const item of $input.all()) {
  if (item.json.items) {
    for (const chan of item.json.items) {
      channelsMap[chan.id] = {
        subscribers: parseInt(chan.statistics.subscriberCount || '0', 10)
      };
    }
  }
}

const videos = [];
const videoDetailsNode = $('Process Video Details').all();
for (const item of videoDetailsNode) {
  if (item.json.videos) {
    videos.push(...item.json.videos);
  }
}

const outliers = [];
const seenVideoIds = new Set();

for (const vid of videos) {
  if (seenVideoIds.has(vid.videoId)) continue;
  seenVideoIds.add(vid.videoId);

  const channelInfo = channelsMap[vid.channelId] || { subscribers: 0 };
  const subs = channelInfo.subscribers;

  if (subs === 0) continue;
  if (subs > maxSubscribers) continue;
  if (vid.views < minViews) continue;

  const ratio = parseFloat((vid.views / subs).toFixed(2));

  if (ratio >= outlierRatioThreshold) {
    outliers.push({
      json: {
        videoId: vid.videoId,
        videoUrl: `https://www.youtube.com/watch?v=${vid.videoId}`,
        title: vid.title,
        channelId: vid.channelId,
        channelTitle: vid.channelTitle,
        views: vid.views,
        subscribers: subs,
        outlierRatio: ratio,
        publishedAt: vid.publishedAt,
        likes: vid.likes,
        comments: vid.comments
      }
    });
  }
}

outliers.sort((a, b) => b.json.outlierRatio - a.json.outlierRatio);
return outliers;

const items = $input.all();
if (items.length === 0) {
  return [{ json: { text: "No YouTube outliers found today." } }];
}

let text = `🚀 **YouTube Outliers Found!** (${items.length} videos)\n\n`;
for (const item of items) {
  const v = item.json;
  text += `📺 **[${v.title}](${v.videoUrl})**\n`;
  text += `👤 Channel: ${v.channelTitle} (${v.subscribers.toLocaleString()} subs)\n`;
  text += `📊 Views: ${v.views.toLocaleString()} (**${v.outlierRatio}x** sub ratio)\n`;
  text += `📅 Published: ${new Date(v.publishedAt).toLocaleDateString()}\n\n`;
}

return [{ json: { text } }];
